text.computeCityPoints:
function computeCityPoints(){
  let popN=0,zoned=0,covSum=0;
  for(let i=0;i<N*N;i++){
    const t=tiles[i],b=t.bld;
    if(t.zone===1){
      zoned++;
      let c=0;
      if(COV.police[i]>0||COV.police2[i]>0)c++; // T222：派出所同計警力覆蓋
      if(COV.fire[i]>0||(COV.fire2&&COV.fire2[i]>0)||(COV.fireHQ&&COV.fireHQ[i]>0))c++;
      if(COV.school[i]>0)c++;
      if(COV.hospital[i]>0||(COV.clinic&&COV.clinic[i]>0))c++;
      if(COV.park[i]>0)c++;
      covSum+=c/5;
    }
    if(b&&!b.ref){
      if([1,127,33,105].includes(b.k))popN+=residentPopulation488(i,b); // T127/T341：住宅摩天樓（root，人口併入城市點數的人口項）
    }
  }
  const svcCov=zoned?covSum/zoned:0;
  return Math.max(0,Math.round((popN+(cityHappy-.6)*400+svcCov*800)*tq('D1',1.05,1)*tq('D4b',1.10,1)));
}

